using Godot;
using Arconist.Core;
using Arconist.Bridge;
using System.Text.Json;
namespace Arconist.GodotApp;
public static class MixedValidation
{
 sealed class Clock:IMonotonicClock{public long Milliseconds{get;set;}}
 public static async void Run(Node owner,SpatialTrack track,string evidenceDir)
 {
 int passed=0,failed=0;var outcomes=new List<object>();var projections=new List<object>();
 void C(bool ok,string why){if(!ok)throw new Exception(why);}
 void T(string name,Action body){try{body();passed++;outcomes.Add(new{name,status="PASS"});GD.Print("PASS S01 "+name);}catch(Exception e){failed++;outcomes.Add(new{name,status="FAIL",error=e.ToString()});GD.Print("FAIL S01 "+name+": "+e.Message);}}
 string Load(string name)=>Godot.FileAccess.GetFileAsString("res://content/"+name);
 Kernel New(string file="s01_mixed.aff"){var k=new Kernel(Chart.Parse(Load(file),ChartProfile.S01Mixed));k.Frame(0);k.Frame(3002);return k;}
 void F(Kernel k,int e)=>k.Frame(e+3002);
 Vector2 Screen(float x,float y)=>track.Camera.UnprojectPosition(SpatialTrack.World(x,y,0));
 (GameplaySession,Clock,SpatialContactAdapter) Session(string file="s01_mixed.aff")
 {var c=new Clock();var s=new GameplaySession(c);s.Start(Load(file),profile:ChartProfile.S01Mixed);c.Milliseconds=3002;s.Frame();track.Refresh(s.Core);return(s,c,new SpatialContactAdapter(s,track));}
 T("production mixed resources and explicit profile N38",()=>{foreach(string n in new[]{"s01_mixed.aff","s01_crossing.aff","s01_grouped.aff"})C(Chart.Parse(Load(n),ChartProfile.S01Mixed).JudgmentUnits>0,n);C(New().Chart.JudgmentUnits==38,"mixedN");});
 T("actual hold curve trace child links and crossing meshes coexist",()=>{var k=New();F(k,4000);track.Refresh(k);C(track.HoldVisualCount==1&&track.ArcVisualCount==6&&k.ArcTaps.Count==1&&track.ArcTapVisual(k.ArcTaps[0])!.Mesh is BoxMesh,"coherent real nodes");});
 T("grouped hold and arc positions read own timing group",()=>{var k=New("s01_grouped.aff");F(k,4500);track.Refresh(k);var a=k.Arcs[0];var root=track.HoldVisual(k.Holds[0].Id)!;var body=root.GetNode<MeshInstance3D>("Body");C(a.Depth==(int)((int)k.DepthAt(4000,1)-k.DepthAt(4500,1))&&a.Depth!=SpatialTrack.HoldDepth(k,4000),"own scale");C(body.Visible&&track.ArcTarget(a.Id)!.Position==SpatialTrack.World(a.TargetX,a.TargetY,0),"shared core geometry");});
 T("nonlinear checkpoint marker and current target agree with curve",()=>{var k=New();F(k,5250);track.Refresh(k);var a=k.Arcs[0];var point=a.Geometry.Point(.5f);var marker=track.ArcVisual(a.Id)!.GetNode<MeshInstance3D>("Checkpoint5250");C(marker.Position.X==SpatialTrack.World(a.Geometry.X0+point.X,point.Y,0).X&&point.X>350&&point.Y>340,"nonlinear marker coordinates");C(track.ArcTarget(a.Id)!.Position==SpatialTrack.World(a.TargetX,a.TargetY,0),"native sampled target");});
 T("production L/R pointer adapter creates two independent retained crossing IDs",()=>{var(s,c,p)=Session();c.Milliseconds=19002;s.Frame();track.Refresh(s.Core);var mid=Screen(0,300);C(p.Press(100,mid)&&p.Press(101,mid,true),"two actual button events");c.Milliseconds++;s.Frame();C(s.Core!.ContactCount==2&&s.Core.Contacts.Select(x=>x.Id).SequenceEqual(new[]{0,1})&&s.Core.Arcs.Where(a=>a.Start==16000).All(a=>a.Holding),"two owners before bypass");c.Milliseconds=19377;s.Frame();C(s.Core.Colors.Values.All(color=>color.Bypass&&color.Owner==-1),"crossing bypass");p.Release(100);C(s.Core.ContactCount==1,"partial UP");p.Release(101);C(s.Core.ContactCount==0,"second UP");s.Home();});
 T("touch drag and CANCEL share same stable core contact adapter",()=>{var(s,c,p)=Session();c.Milliseconds=7002;s.Frame();track.Refresh(s.Core);C(p.Press(1003,Screen(-255,200)),"touch down");int id=s.Core!.Contacts.Single().Id;c.Milliseconds=8002;s.Frame();p.Move(1003,Screen(45,300));C(s.Core.Contacts.Single().Id==id&&s.Core.Pure<38,"MOVE no initial tap");C(p.Release(1003,true)&&s.Core.ContactCount==0,"CANCEL");s.Home();});
 T("camera and actual viewport resizing keep curve child and links selectable",()=>{var v=(SubViewport)track.GetViewport();var parent=(SubViewportContainer)v.GetParent();var old=v.Size;bool stretch=parent.Stretch;parent.Stretch=false;try{foreach(var size in new[]{new Vector2I(610,550),new Vector2I(732,660)})foreach(bool alt in new[]{false,true}){v.Size=size;C(v.Size==size,"actual size");track.SetView(alt);var k=New();foreach(int e in new[]{4000,5250,9000,12000,13001,16000}){F(k,e);track.Refresh(k);var point=e==9000?k.ArcTaps[0].InputTarget:new SkyPoint((e>=12000&&e<16000)?0:k.Arcs.First(a=>a.Start<=e&&e<=a.End&&!a.Data.Trace).TargetX,(e>=12000&&e<16000)?300:k.Arcs.First(a=>a.Start<=e&&e<=a.End&&!a.Data.Trace).TargetY,0);var screen=Screen(point.X,point.Y);C(v.GetVisibleRect().HasPoint(screen)&&track.PickSky(screen,out var sky)&&ArcSpatial.Matches(point.X,point.Y,sky),"visible ray targetE"+e);projections.Add(new{e,alt,width=size.X,height=size.Y,x=screen.X,y=screen.Y});}}}finally{v.Size=old;parent.Stretch=stretch;track.SetView(false);}});
 T("renderer cannot mutate contact links group records score or gauge",()=>{var k=New();F(k,16000);string Snapshot()=>JsonSerializer.Serialize(new{k.Pure,k.Score,k.Health,k.RecorderCalls,groups=k.TimingGroups.Select(g=>new{g.Id,g.FrameOffset,g.Index}),arcs=k.Arcs.Select(a=>new{a.Id,a.Depth,a.Cache,a.Holding,a.Records,owner=a.Color.Owner,a.Color.Bypass,a.Color.BypassTime})});string before=Snapshot();for(int i=0;i<20;i++)track.Refresh(k);C(before==Snapshot(),"renderer writes gameplay");});
 T("manual modal freeze keeps grouped long notes and fresh input gating",()=>{var(s,c,p)=Session();c.Milliseconds=7002;s.Frame();track.Refresh(s.Core);s.Key('F',true);p.Press(100,Screen(-255,200));c.Milliseconds=8252;s.Frame();track.Refresh(s.Core);var pos=track.ArcTarget(s.Core!.Arcs[0].Id)!.Position;var panel=new PausePanel();owner.AddChild(panel);panel.Bind(s);s.Changed+=_=>panel.Sync();s.Pause();c.Milliseconds+=60000;s.Frame();track.Refresh(s.Core);C(panel.Visible&&s.PauseModalActive&&s.Core.Timeline.EffectiveTime==5250&&pos==track.ArcTarget(s.Core.Arcs[0].Id)!.Position,"freeze");C(!p.Press(101,Screen(0,300),true),"modal DOWN gate");p.Release(100);C(s.Core.ContactCount==1&&s.Core.Holds[0].Latched,"paused UP retains keyboard");C(panel.Resume()&&!panel.Visible&&s.Core.Pure<38,"explicit dismissal");owner.RemoveChild(panel);panel.QueueFree();s.Home();});
 T("full production bridge camera pointer and audio-independent mixed result",()=>{var(s,c,p)=Session();for(int e=1;e<=24121;e++){c.Milliseconds=e+3002;s.Frame();foreach(var note in s.Core!.Notes.Where(n=>n.Start==e)){s.Contact(200+note.Data.Ordinal,note.Lane,true);s.Contact(200+note.Data.Ordinal,note.Lane,false);}if(e==4000){track.Refresh(s.Core);s.Key('F',true);p.Press(100,Screen(-255,200));}if(e>4000&&e<6500){float u=(e-4000)/2500f;float z=(float)Math.Sin(u*Math.PI/2);p.Move(100,Screen(-255+510*z,200+200*z));}if(e==6500){s.Key('F',false);p.Release(100);}if(e==9000){p.Press(100,Screen(0,300));p.Release(100);}if(e==12000)p.Press(100,Screen(0,300));if(e==14001)p.Release(100);if(e==16000){p.Press(100,Screen(0,300));p.Press(101,Screen(0,300),true);}if(e==17000){p.Release(100);p.Release(101);}if(e%100==0)track.Refresh(s.Core);}p.Prune();track.Refresh(s.Core);C(s.Core!.Result!.Score==10000038&&s.Core.Result.MaxCombo==38&&p.Count==0&&s.HeldCount==0&&s.Core.Arcs.All(a=>!track.ArcVisual(a.Id)!.Visible),"complete38/reset");s.Home();track.Refresh(null);C(track.ArcVisualCount==0&&track.HoldVisualCount==0,"menu cleanup");});
 T("new run restores fresh owner group curve and consumed states",()=>{var k=New();F(k,16000);track.Refresh(k);var old=track.ArcVisual(k.Arcs[0].Id)!;var fresh=New();track.Refresh(fresh);C(!old.IsInsideTree()&&fresh.Arcs.All(a=>!a.Color.Bypass&&a.Color.Owner==-1)&&fresh.ArcTaps.All(c=>!c.Consumed)&&fresh.Holds.All(h=>!h.Latched),"fresh state");});
 var backend=new GodotBgmBackend();owner.AddChild(backend);var clock=new Clock();var audible=new GameplaySession(clock,backend);var diagnostics=new List<BgmDiagnostic>();audible.Audio!.Diagnostic+=diagnostics.Add;
 T("real Godot bundled music starts once for selected mixed chart",()=>{audible.Start(Load("s01_mixed.aff"),0,"S01-mixed","res://content/audio/clockwork_steps.wav.bytes",profile:ChartProfile.S01Mixed);clock.Milliseconds=3000;audible.Frame();C(!backend.Player.Playing,"strict equality");clock.Milliseconds=3002;audible.Frame();C(backend.Player.Playing&&audible.Audio!.Starts==1,"actual backend start API");});
 await owner.ToSignal(owner.GetTree().CreateTimer(.05),SceneTreeTimer.SignalName.Timeout);
 T("real mixed audio pause seek unpause and menu unload",()=>{clock.Milliseconds=8252;audible.Frame();audible.Pause();clock.Milliseconds+=60000;audible.Frame();C(backend.Player.StreamPaused&&audible.Core!.Timeline.EffectiveTime==5250,"paused");C(audible.Resume()&&diagnostics.Any(d=>d.Kind=="BGM_SEEK_REQUEST"&&d.SeekMilliseconds==5250),"logical seek");audible.Home();C(backend.Player.Stream==null&&!backend.Player.Playing,"unloaded");});
 backend.StopAndUnload();owner.RemoveChild(backend);backend.QueueFree();track.Refresh(null);track.SetView(false);
 await owner.ToSignal(owner.GetTree().CreateTimer(.1),SceneTreeTimer.SignalName.Timeout);
 File.WriteAllText(Path.Combine(evidenceDir,"mixed-headless.json"),JsonSerializer.Serialize(new{passed,failed,skipped=0,outcomes,projections,diagnostics,human="PENDING",independentNewProduction="NOT RUN"},new JsonSerializerOptions{WriteIndented=true}));GD.Print($"S01 headless: {passed+failed}; passed:{passed}; failed:{failed}; skipped:0");owner.GetTree().Quit(failed==0?0:1);
 }
}
